var turnSeen=null,audioCtx=null,soundOn=localStorage.diceSound!=="off",vibeOn=localStorage.diceVibrate!=="off",canVibrate=typeof navigator.vibrate==="function"&&(navigator.maxTouchPoints>0||matchMedia("(any-pointer: coarse)").matches);
function turnKey(){return state.turn+":"+state.players.length+":"+state.players.reduce((s,p)=>s+Object.keys(p.scores||{}).length,0)}function markTurnSeen(){turnSeen=turnKey()}
// Runs once per real turn change (dedupe key = active seat + filled categories), never per poll/render.
function afterTurnChange(by){let k=turnKey();if(k===turnSeen)return;turnSeen=k;if(state.players.every(p=>playerDone(p)))return;let human=!isCpu(state.turn),mine=online.code?human&&isMyTurn():human,alertMe=mine&&by!=="human";if(alertMe&&online.code){let r=document.getElementById("roller"),bd=document.getElementById("board");if(r&&(r.hidden||(bd&&bd.hidden))){setAppView("dice");rollState.open=true;renderRoller()}}if(!online.code||by==="human"||alertMe)scrollToDice();if(alertMe)showTurnNotice()}
function scrollToDice(){requestAnimationFrame(()=>{let t=document.getElementById("turn"),r=document.getElementById("roller"),el=t&&!t.hidden?t:r&&!r.hidden?r:null;if(!el)return;let h=document.querySelector("header"),off=h&&getComputedStyle(h).position==="sticky"?h.getBoundingClientRect().height:0,a=el.getBoundingClientRect(),b=r&&!r.hidden?r.getBoundingClientRect():a;if(a.top>=off&&b.bottom<=innerHeight)return;window.scrollTo({top:Math.max(0,a.top+scrollY-off-6),behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"})})}
function audioUnlock(){if(!soundOn)return;try{if(!audioCtx){let C=window.AudioContext||window.webkitAudioContext;if(!C)return;audioCtx=new C()}if(audioCtx.state==="suspended")audioCtx.resume().catch(()=>{})}catch(e){}}
["pointerdown","keydown","touchend"].forEach(ev=>addEventListener(ev,audioUnlock,{passive:true,capture:true}));
// Soft single "bimm": short sine bell with fast decay; silently skipped if the browser blocks audio (no retries).
function playTurnTone(){if(!soundOn)return;try{if(!audioCtx){let C=window.AudioContext||window.webkitAudioContext;if(!C)return;audioCtx=new C()}let a=audioCtx,beep=()=>{if(a.state!=="running")return;let t=a.currentTime,g=a.createGain();g.gain.setValueAtTime(1e-4,t);g.gain.exponentialRampToValueAtTime(.09,t+.012);g.gain.exponentialRampToValueAtTime(1e-4,t+.42);g.connect(a.destination);[[880,1],[1760,.25]].forEach(([f,v])=>{let o=a.createOscillator(),og=a.createGain();o.type="sine";o.frequency.setValueAtTime(f,t);og.gain.value=v;o.connect(og);og.connect(g);o.start(t);o.stop(t+.45)})};if(a.state==="running")beep();else a.resume().then(beep).catch(()=>{})}catch(e){}}
