function renderAlertToggles(){let th=lang==="th",s=document.getElementById("soundToggle"),v=document.getElementById("vibeToggle");if(s){let l=soundOn?(th?"เสียง":"Sound"):(th?"ปิดเสียง":"Sound off");s.innerHTML='<span class="ic">'+(soundOn?"🔊":"🔇")+'</span><span class="lbl">'+l+"</span>";s.title=l;s.setAttribute("aria-label",l);s.setAttribute("aria-pressed",String(soundOn));s.classList.toggle("off",!soundOn)}if(v){v.hidden=!canVibrate;if(canVibrate){let l=vibeOn?(th?"สั่น":"Vibration"):(th?"ปิดสั่น":"Vibration off");v.innerHTML='<span class="ic">'+(vibeOn?"📳":"📴")+'</span><span class="lbl">'+l+"</span>";v.title=l;v.setAttribute("aria-label",l);v.setAttribute("aria-pressed",String(vibeOn));v.classList.toggle("off",!vibeOn)}}}
document.getElementById("soundToggle").onclick=()=>{soundOn=!soundOn;localStorage.diceSound=soundOn?"on":"off";renderAlertToggles();if(soundOn){audioUnlock();playTurnTone()}};
